CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'agronomist',created REAL NOT NULL);
        CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires REAL NOT NULL);
        CREATE TABLE IF NOT EXISTS config(key TEXT PRIMARY KEY,value TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS scans(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id),client_id TEXT NOT NULL,created REAL NOT NULL,updated REAL NOT NULL,region TEXT NOT NULL,crop TEXT NOT NULL,note TEXT NOT NULL,lat REAL,lon REAL,image TEXT NOT NULL,status TEXT NOT NULL,stage INTEGER NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0,result TEXT,error TEXT,UNIQUE(user_id,client_id));
        CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT,scan_id TEXT REFERENCES scans(id),created REAL NOT NULL,kind TEXT NOT NULL,payload TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY,scan_id TEXT NOT NULL REFERENCES scans(id),kind TEXT NOT NULL,query TEXT NOT NULL,url TEXT NOT NULL,title TEXT NOT NULL,content TEXT NOT NULL,retrieved REAL NOT NULL,provider TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS ledger(id TEXT PRIMARY KEY,scan_id TEXT NOT NULL REFERENCES scans(id),created REAL NOT NULL,type TEXT NOT NULL,query TEXT NOT NULL,result TEXT NOT NULL,impact TEXT NOT NULL,saving REAL,source_ids TEXT NOT NULL,currency TEXT NOT NULL DEFAULT 'USD');
        CREATE TABLE IF NOT EXISTS assignments(id TEXT PRIMARY KEY,region TEXT NOT NULL,cluster_key TEXT NOT NULL,assignee TEXT NOT NULL,note TEXT NOT NULL,status TEXT NOT NULL,created REAL NOT NULL,created_by TEXT NOT NULL REFERENCES users(id));
        CREATE TABLE IF NOT EXISTS alerts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),scan_id TEXT REFERENCES scans(id),created REAL NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,acknowledged INTEGER NOT NULL DEFAULT 0,old_plan TEXT,new_plan TEXT);
        CREATE TABLE IF NOT EXISTS devices(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),created REAL NOT NULL);
        CREATE TABLE IF NOT EXISTS pairing(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires REAL NOT NULL);
        CREATE INDEX IF NOT EXISTS scans_region ON scans(region,created);
        CREATE INDEX IF NOT EXISTS sources_scan ON sources(scan_id);
        CREATE INDEX IF NOT EXISTS events_scan ON events(scan_id,id);
